/*
 * TASK PROBLEM STATEMENT:
 * -----------------------------------------------------------------------------
 * Problem 18:
 * Write a function of testing of the sampling U_1, ..., U_n generated by the
 * generator of Example 5 by the First Test (Uniformity Chi-Square Test, alpha = 0.1).
 * 
 * Generator:
 *   z_i = (201 * z_{i-1} + 13) mod 2^9,   z_0 = 2103
 *   U_i = z_i / 512.0
 * 
 * Bitwise Optimization Breakdown:
 *   - 201 * z   => (z << 7) + (z << 6) + (z << 3) + z
 *   - mod 2^9   => & 511 (0x1FF)
 *   - Subinterval index (k = 128 = 2^7): floor(U_i * 128) = z_i >> 2
 * -----------------------------------------------------------------------------
 */

#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <iomanip>

using namespace std;

// Bitwise LCG Step from Example 5: z_i = (201 * z_{i-1} + 13) mod 2^9
inline unsigned int nextLCG_Ex5_Bitwise(unsigned int z) {
    // 201 * z = (z << 7) + (z << 6) + (z << 3) + z
    unsigned int mult = (z << 7) + (z << 6) + (z << 3) + z;
    return (mult + 13) & 511; // mod 512 (2^9 - 1 = 511)
}

// Standard LCG Step for benchmark comparison
inline unsigned int nextLCG_Ex5_Standard(unsigned int z) {
    return (201 * z + 13) % 512;
}

// Chi-Square critical value approximation (Wilson-Hilferty) for alpha = 0.1
inline double getChiSquareCritical_Alpha01(int df) {
    // For alpha = 0.10, upper standard normal quantile Z_{0.90} = 1.2815515655
    const double z_alpha = 1.2815515655;
    double term = 1.0 - (2.0 / (9.0 * df)) + z_alpha * sqrt(2.0 / (9.0 * df));
    return df * pow(term, 3);
}

// First Test: Chi-Square Uniformity Test Function
void runFirstUniformityTest(int n, int k = 128, double alpha = 0.1) {
    vector<int> freq(k, 0);
    unsigned int z = 2103 & 511; // Initial seed z_0 = 2103 mod 512 = 55

    cout << "=== SAMPLE GENERATION & FIRST 10 VALUES (U_i = z_i / 512) ===\n";
    cout << left << setw(8) << "Step" << setw(12) << "z_i" << setw(15) << "U_i" << "Subinterval (j)\n";
    cout << "-----------------------------------------------------\n";

    for (int i = 1; i <= n; ++i) {
        z = nextLCG_Ex5_Bitwise(z);
        double U_i = static_cast<double>(z) / 512.0;
        
        // Bitwise subinterval mapping: for k = 128 (2^7) and M = 512 (2^9), index = z >> 2
        int j = z >> 2; 
        freq[j]++;

        if (i <= 10) {
            cout << left << "U_" << setw(6) << i 
                 << setw(12) << z 
                 << setw(15) << fixed << setprecision(6) << U_i 
                 << (j + 1) << " / " << k << "\n";
        }
    }
    cout << "\n";

    // Compute Chi-Square statistic: chi^2 = (k / n) * sum_{j=1}^k (f_j - n/k)^2
    double expected = static_cast<double>(n) / k;
    double sum_sq_diff = 0.0;

    for (int j = 0; j < k; ++j) {
        double diff = freq[j] - expected;
        sum_sq_diff += diff * diff;
    }

    double chi_square = (static_cast<double>(k) / n) * sum_sq_diff;
    int df = k - 1;
    double critical_value = getChiSquareCritical_Alpha01(df);

    cout << "=== I TEST: UNIFORMITY CHI-SQUARE TEST RESULTS ===\n";
    cout << "Sample Size (n):              " << n << "\n";
    cout << "Subintervals (k):             " << k << " (k >= 100 satisfied)\n";
    cout << "Degrees of Freedom (k - 1):   " << df << "\n";
    cout << "Significance Level (alpha):   " << alpha << "\n";
    cout << "Expected Frequency (n / k):   " << fixed << setprecision(2) << expected << "\n";
    cout << "Computed Chi-Square (X^2):    " << fixed << setprecision(4) << chi_square << "\n";
    cout << "Critical Value X^2_{" << df << ", 0.1}: " << fixed << setprecision(4) << critical_value << "\n\n";

    cout << "=== HYPOTHESIS DECISION ===\n";
    if (chi_square > critical_value) {
        cout << "RESULT: REJECT H_0 (X^2 > Critical Value).\n";
        cout << "Conclusion: The sample U_1...U_n is NOT uniformly distributed on [0, 1].\n";
        cout << "(Note: Because M = 2^9 = 512 has a short period of 512, large n repeats cycles identically.)\n\n";
    } else {
        cout << "RESULT: ACCEPT H_0 (X^2 <= Critical Value).\n";
        cout << "Conclusion: The sample U_1...U_n passes the uniformity test at alpha = " << alpha << ".\n\n";
    }
}

int main() {
    // Fast I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    // Run First Test on n = 10,000 generated numbers with k = 128 subintervals and alpha = 0.1
    const int sample_size = 10000;
    const int k_intervals = 128; // >= 100 as required by the test rules
    const double alpha = 0.1;

    runFirstUniformityTest(sample_size, k_intervals, alpha);

    // Performance Benchmark (100,000,000 iterations)
    const int iterations = 100000000;
    volatile unsigned int dummy1 = 55;
    volatile unsigned int dummy2 = 55;

    auto start_bw = chrono::high_resolution_clock::now();
    for (int i = 0; i < iterations; ++i) {
        dummy1 = nextLCG_Ex5_Bitwise(dummy1);
    }
    auto end_bw = chrono::high_resolution_clock::now();
    chrono::duration<double> bw_time = end_bw - start_bw;

    auto start_std = chrono::high_resolution_clock::now();
    for (int i = 0; i < iterations; ++i) {
        dummy2 = nextLCG_Ex5_Standard(dummy2);
    }
    auto end_std = chrono::high_resolution_clock::now();
    chrono::duration<double> std_time = end_std - start_std;

    cout << "=== BENCHMARK RESULTS (" << iterations << " iterations) ===\n";
    cout << "Bitwise Generator Time:  " << bw_time.count() << " seconds\n";
    cout << "Standard Generator Time: " << std_time.count() << " seconds\n";

    double speedup = std_time.count() / bw_time.count();
    cout << "Bitwise version is ~" << fixed << setprecision(2) << speedup << "x FASTER!\n";

    return 0;
}
